// Plan disjoint finite-tail intervals, including splits inside a 2-byte cell.
// Samples choose provisional separators only. A second exact full pass proves
// their resource masses (or reports oversize); no rowwise landing or sorting.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
#include <filesystem>
#include <fstream>
#include <string_view>
#include <unordered_map>
#include <vector>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;using K=pair<string_view,bool>;
constexpr U A=258,S=4096; struct Cell{Q d,r;};struct Sample{string s;bool e;U freq;};struct Mass{Q d=0,bytes=0,r=0;};
Q reads(){ifstream f("/proc/self/io");string k;Q x;while(f>>k>>x)if(k=="read_bytes:")return x;abort();}U get(istream& f){U v;assert(f.read((char*)&v,4));return v;} U cell(K k){auto s=k.first;return (2+(unsigned char)s[0])*A+(s.size()>1?2+(unsigned char)s[1]:U(k.second));}
int main(int ac,char**av){assert(ac>=6&&ac<=8);bool compact=ac>=7;Q sink=ac==8?stoull(av[7]):0;fs::path tape=av[1],loc=av[2],hist=av[3],out=av[4];Q n=stoull(av[5]);assert(n&&n<=1010000000&&!fs::exists(out));ifstream hf(hist,ios::binary);vector<Cell>h(A*A);assert(hf.read((char*)h.data(),h.size()*sizeof(Cell)));Q desc=0,rows=0;for(auto c:h){desc+=c.d;rows+=c.r;}assert(rows==n);U k=fs::file_size(loc)/4-1;assert(k<=26000000);vector<uint8_t>freq(k);unordered_map<U,U>high;ifstream lf(loc,ios::binary);U off=get(lf);assert(!off);for(U i=0;i<k;i++){U end=get(lf);assert(end>off);U f=end-off;freq[i]=min(255u,f);if(f>=255){high.emplace(i,f);assert(high.size()<=250000);}off=end;}Q live=fs::file_size(tape)+fs::file_size(hist)+fs::file_size(loc)+13ull*off;
 const char* text=nullptr;if(compact){assert(fs::file_size(av[6])==n &&fs::file_size(tape)==16ull*k);int fd=open(av[6],O_RDONLY);assert(fd>=0);text=(const char*)mmap(nullptr,n,PROT_READ,MAP_PRIVATE,fd,0);close(fd);assert(text!=MAP_FAILED);madvise((void*)text,n,MADV_SEQUENTIAL);}auto scan=[&](auto visit){ifstream f(tape,ios::binary);if(compact){U r[4];Q j=0;while(f.read((char*)r,16)){auto [pos,h,id,mult]=r;U len=h&0x7fffffffu;bool eof=h>>31;assert(id<k&&pos+Q(len)<=n&&mult==(freq[id]==255?high.at(id):U(freq[id])));for(U o=0;o<len-(eof?0:8);o++,j++)visit(j,K{{text+pos+o,len-o},eof},mult);if(!(id%32768))assert(reads()<=5*n);}assert(j==desc&&f.eof());return;}vector<char>raw;U id;Q j=0;while(f.read((char*)&id,4)){U tag=get(f),len=tag&0x7fffffff;bool eof=tag>>31;assert(id<k&&len>0&&len<=1<<20&&(eof||len>8));raw.resize(len);assert(f.read(raw.data(),len));U mult=freq[id]==255?high.at(id):freq[id];for(U o=0;o<len-(eof?0:8);o++,j++)visit(j,K{{raw.data()+o,len-o},eof},mult);if(!(id%32768))assert(reads()<=5*n);}assert(f.eof()&&j==desc);};
 // One pseudo-random offset per physical block avoids periodic stride aliases.
 vector<Sample>s;s.reserve(desc/S+2);Q sampled=0,next=0,seed=0;scan([&](Q j,K v,U f){if(!(j%S)){seed=seed*6364136223846793005ull+1442695040888963407ull;next=j+((seed>>32)%S);}if(j==next){sampled+=v.first.size();assert(sampled<=32<<20);s.push_back({string(v.first),v.second,f});}});auto key=[](const Sample&x)->K{return {x.s,x.e};};sort(s.begin(),s.end(),[&](auto&a,auto&b){return key(a)<key(b);});vector<Sample>piv;Mass a;for(size_t i=0;i<s.size();i++){auto &x=s[i];a.d+=S;a.r+=Q(S)*x.freq;a.bytes+=Q(S)*x.s.size();if(i+1<s.size()&&key(x)!=key(s[i+1])&&(a.d>=(sink?90000:450000)||a.r>=(sink?180000:750000)||a.bytes>=(sink?4000000u:compact?12000000u:22000000u))){piv.push_back(x);a={};}}assert(piv.size()<65536);vector<Sample>().swap(s);vector<U>bounds(A*A+1);U p=0;for(U c=0;c<=A*A;c++){while(p<piv.size()&&cell(key(piv[p]))<c)p++;bounds[c]=p;}assert(p==piv.size());vector<Mass>bins(piv.size()+1);scan([&](Q,K v,U f){U c=cell(v);auto it=lower_bound(piv.begin()+bounds[c],piv.begin()+bounds[c+1],v,[&](auto &x,K y){return key(x)<y;});auto &b=bins[it-piv.begin()];b.d++;b.r+=f;b.bytes+=v.first.size();});
 ofstream o(out,ios::binary);U count=bins.size();o.write((char*)&count,4);Q size=4;Mass total,mx;U bad=0;for(U i=0;i<count;i++){auto b=bins[i];mx.d=max(mx.d,b.d);mx.r=max(mx.r,b.r);mx.bytes=max(mx.bytes,b.bytes);total.d+=b.d;total.r+=b.r;total.bytes+=b.bytes;bad+=(b.d>1100000||b.r>2000000||b.bytes>(64u<<20));U tag=i<piv.size()?U(piv[i].s.size())|(U(piv[i].e)<<31):0;size+=sizeof(b)+4+(tag&0x7fffffffu);assert(live+size<=2*n);o.write((char*)&b,sizeof(b)).write((char*)&tag,4);if(i<piv.size())o.write(piv[i].s.data(),piv[i].s.size());}o.close();assert(o&&total.d==desc&&total.r==n&&reads()<=5*n);printf("PLAN windows=%u over_budget=%u descriptors=%llu rows=%llu total_key_bytes=%llu max_descriptors=%llu max_rows=%llu max_key_bytes=%llu naive_tape_scan_bytes=%llu counted_with_plan=%llu reads=%llu\n",count,bad,(unsigned long long)desc,(unsigned long long)rows,(unsigned long long)total.bytes,(unsigned long long)mx.d,(unsigned long long)mx.r,(unsigned long long)mx.bytes,(unsigned long long)(count*(fs::file_size(tape)+(compact?n:0))),(unsigned long long)(live+size),(unsigned long long)reads());if(sink){U fails=0;Q worst=0;for(auto b:bins){Q joint=live+size+sink+(1u<<20)+28*b.d+b.bytes+9*b.r;worst=max(worst,joint);fails+=joint>2*n;}printf("JOINT reserved_sink=%llu oversized=%u worst=%llu\n",(unsigned long long)sink,fails,(unsigned long long)worst);bad+=fails;}return bad?75:0;}
